using System.IO;  namespace BlueArchiveLauncher.Core.Services;  public sealed class FileLogger {     private readonly object _gate = new();     private readonly string _logDirectory = Path.Combine(         Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),         "BlueArchiveLauncher",         "logs");      public FileLogger()     {         Directory.CreateDirectory(_logDirectory);     }      public void Info(string message) => Write("INFO", message);      public void Warn(string message) => Write("WARN", message);      public void Error(string message, Exception? exception = null)     {         var detail = exception is null ? message : $"{message} | {exception}";         Write("ERROR", detail);     }      private void Write(string level, string message)     {         var line = $"{DateTimeOffset.Now:yyyy-MM-dd HH:mm:ss.fff zzz} [{level}] {message}{Environment.NewLine}";         lock (_gate)         {             File.AppendAllText(                 Path.Combine(_logDirectory, $"{DateTime.Now:yyyy-MM-dd}.log"),                 line);         }     } }